package com.steven.assets.service.srpp.settings;
import com.steven.assets.security.CurrentUserContext;import com.steven.assets.service.UserAdminService;import com.steven.assets.model.AppUser;import com.steven.assets.dto.SrppClaudeAuthDto;import org.junit.jupiter.api.*;import java.util.*;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
class SrppClaudeAuthServiceTest {
 CurrentUserContext current;UserAdminService users;SrppClaudeAuthPort port;SrppClaudeAuthService service;AppUser admin;
 @BeforeEach void setup(){current=new CurrentUserContext();current.setEffectiveUserId(7L);current.setRole("ADMIN");current.setStatus("ACTIVE");users=mock(UserAdminService.class);port=mock(SrppClaudeAuthPort.class);admin=new AppUser();admin.setId(7L);admin.setEmail("admin@example.test");admin.setRole("ADMIN");admin.setStatus("ACTIVE");when(users.configuredAdmin()).thenReturn(Optional.of(admin));when(users.isConfiguredAdmin(admin.getEmail())).thenReturn(true);service=new SrppClaudeAuthService(current,users,port);}
 @Test void freshAuthorityRejectsOrdinaryOwnerOtherAdminDisabledAndNonConfiguredBeforeHost(){for(int i=0;i<4;i++){current.setEffectiveUserId(i==0?8L:7L);current.setRole(i==1?"USER":"ADMIN");admin.setStatus(i==2?"DISABLED":"ACTIVE");when(users.isConfiguredAdmin(admin.getEmail())).thenReturn(i!=3);assertThatThrownBy(()->service.call("state","a".repeat(43),"claude",null,null)).isInstanceOf(SrppClaudeAuthProblem.class);}verifyNoInteractions(port);}
 @Test void serverOwnerBindingAndClosedBodyReachOnlyAuthPort(){when(port.call(eq("state"),any())).thenReturn(SrppClaudeAuthDto.parse("{\"schemaVersion\":1,\"toolId\":\"claude\",\"loginState\":\"VALID\",\"expiresAt\":\"2099-11-16T00:00:00Z\",\"code\":null}"));assertThat(service.call("state","a".repeat(43),"claude",null,null)).isInstanceOf(SrppClaudeAuthDto.AuthLocalState.class);verify(port).call(eq("state"),argThat(n->n.size()==3&&n.path("ownerId").asLong()==7&&n.path("sessionBinding").asText().equals("a".repeat(43))));}
 @Test void callerOwnerExtraKeysAndMalformedCodeRejectedWithoutHost(){for(String raw:List.of("{\"toolId\":\"claude\",\"ownerId\":8}","{\"toolId\":\"claude\",\"toolId\":\"other\"}"))assertThatThrownBy(()->service.call("start","a".repeat(43),null,null,raw)).isInstanceOf(SrppClaudeAuthProblem.class);assertThatThrownBy(()->service.call("complete","a".repeat(43),null,"b".repeat(43),"{\"code\":\"secret code#state\"}")).isInstanceOf(SrppClaudeAuthProblem.class);verifyNoInteractions(port);}
 @Test void upstreamUrlAndNativeDetailsNeverLeakFromInvalidPayload(){when(port.call(any(),any())).thenReturn(SrppClaudeAuthDto.parse("{\"secret\":\"oauth-code-native-secret\"}"));assertThatThrownBy(()->service.call("state","a".repeat(43),"claude",null,null)).hasMessageNotContaining("oauth-code");}
}
